example.code:
 // it's possible to specify extra attributes for the connection
 ConnectionAttributes extraAttributes = ConnectionAttributes.None;

 // list of Connection objects that is supported by the client.
 Type[] supportedTypes = new Type[] {  typeof(GRPCConnection), typeof(RemotingConnection)  }

 // discover the actual connection
 Connection conn = null;

 try 
 {
	   conn = ConnectionSettings.GetConnection("10.10.7.1", extraAttributes, supportedTypes);
 }
 catch (DataMinerException de)
 {
	   // no connection settings could be discovered,
	   // or none of the connection types found matched a supported type
 }

 // try to authenticate
 conn.Authenticate();

 // ...

 // if you have multiple IP addresses on the system, the IP address
 // to use when checking configuration ranges can be explicitly 
 // specified. 
 string myIP = "10.11.1.1";

 // host to detect settings for
 string hostName = "10.10.7.1";

 ConnectionSettings settings = null;
 try 
 {
		settings = ConnectionSettings.AutoDetectSettingsFor(myIP, hostName);

		Console.WriteLine("Connection Type: {0}", settings.Type);
		Console.WriteLine("Use Polling: {0}", settings.UsePolling);
		Console.WriteLine("Needs Zipping: {0}", settings.NeedsZipping);
 } 
 catch (DataMinerException de)
 {
		// failed to discover settings, or no appropriate settings found
 }

member.example:
This example shows how to set up and wait for a connection

// create a connection object
Connection conn = ConnectionSettings.GetConnection("localhost");

// set parameters to use while waiting for a connection
ConnectionWaitState ws = new ConnectionWaitState();
ws.MaxRetries = 10;
ws.RetryInterval = 1000;

// try to authenticate, and retry every second when it fails
if (conn.WaitForConnection(ws))
{
    // connected
}

Events can be used in combination with the 
 method
to provide status updates in GUI applications.

public void StartConnect(string hostname)
{
  ConnectionWaitState ws = new ConnectionWaitState();

  ws.OnStartAttempt += new EventHandler(Wait_OnStartAttempt);
  ws.OnFailedAttempt += new ConnectionWaitState.ErrorEventHandler(Wait_OnFailedAttempt);
  ws.OnFinishedSuccess += new EventHandler(Wait_OnSuccess);
  ws.OnFinishedFailure += new EventHandler(Wait_OnFailed);

  ws.MaxRetries = 10;

  Connection conn = ConnectionSettings.GetConnection(hostname);
  conn.WaitForConnectionAsync(ws);
}

private void Wait_OnStartAttempt(object sender, EventArgs e)
{
  // ... Update progress bar
} 

private void Wait_OnFailedAttempt(object sender, ConnectionWaitState.ErrorEventArgs e)
{
  // ... Update log with e.Exception.Message
}

private void Wait_OnSuccess(object sender, EventArgs e)
{
  // ... Update controls etc to "connected" state.
}

private void Wait_OnFailed(object sender, EventArgs e)
{
  // ... Show "connected failed" dialog.
}

example.code:
Connection conn = ConnectionSettings.GetConnection("localhost");

// set parameters to use while waiting for a connection
ConnectionWaitState ws = new ConnectionWaitState();
ws.MaxRetries = 10;
ws.RetryInterval = 1000;
ws.NoAuthentication = true;

// try to authenticate, and retry every second when it fails
if (conn.WaitForConnection(ws))
{
    // connection is working, but we still need to authenticate
    // manually.

    try 
    {
	    conn.Authenticate();
	}
	catch (DataMinerException)
	{
		// authentiaction failed, or the dataminer is not running or
		// starting up
	}    
}

