member.example:
This example shows how to set up a .NET remoting connection from a client application

// create a TCP channel. A "0" parameter needs to be specified to make this a 
// server channel rather than a client channel only. (needed for callbacks)
// The 0 as port number indicates that a port number can be chosen on our behalf
TcpChannel chan = new TcpChannel(0);
ChannelServices.RegisterChannel(chan, false);

// Creates a proxy for the well-known object indicated by the specified type and URL.
string connectionUri = "http://localhost:8004/SLNetService";
ISLNet slNet = (ISLNet)Activator.GetObject(typeof(ISLNet), connectionUri);

This example shows how to use the SLNetCallback class to subscribe a callback method
for your client

public class RemotingCallback : SLNetCallback
{
	protected override void InternalNewMessageHandler(DMSMessage msg)
	{
		// Your implementation here
		Console.WriteLine("## Callback: " + msg);
	}
}

public class Client
{
	public Connect()
	{
		...
		SLNetCallback cb = new RemotingCallback();			
		CreateSubscriptionMessage sm = ...;
		sm.Callback = new NewMessageEventHandler(cb.NewMessageEventHandler);
		slNet.HandleMessage(sm);
		...
	}
}

