example.code:
public class SampleEventMessage : EventMessage, IFilterableMessage<int>
   {
       public List<int> MyList { get; private set; }

   public SampleEventMessage() { MyList = new List<int>(); }
   public SampleEventMessage(SampleEventMessage evt) : this() { MyList = evt.MyList; }
   public IFilterableMessage AggregateMessages(DMSMessage originalMessage, IEnumerable<IFilterableMessage> messagesToAggregate)
   {
       var originalEvt = originalMessage as SampleEventMessage;
       if (originalEvt == null)
           throw new ArgumentException(nameof(originalMessage) + " was not of correct type: " + typeof(SampleEventMessage).Name);
       if (!messagesToAggregate.All(oneM => oneM is SampleEventMessage))
           throw new ArgumentException("Not all messages in messagesToAggregate were of type " + typeof(SampleEventMessage).Name);

       var evt = new SampleEventMessage(originalEvt);
       evt.MyList.Clear();

       foreach (var sem in messagesToAggregate.OfType<SampleEventMessage>())
       {
           evt.MyList.AddRange(sem.MyList);
       }

       return evt;
   }

   public IFilterableMessage<int> CreateInterestingMessage(FilterElement<int> filterElement)
   {
       var evt = new SampleEventMessage();
       evt.MyList.AddRange(MyList.Where(filterElement.getLambda()));
       return evt;
   }

   public bool HasInterestingObjects(FilterElement<int> filterElement)
   {
       return MyList.Any(filterElement.getLambda());
   }
}

